        appOptions: JSON.parse('[\u0022Google Meet\u0022,\u0022Mailchimp\u0022,\u0022Zoom\u0022,\u0022Loom\u0022,\u0022Gmail\u0022,\u0022Linear\u0022,\u0022Trello\u0022,\u0022Notion\u0022,\u0022Jira\u0022]'),
        current: null,
        add: { app: 'Google Meet', clientId: '', clientSecret: '', authBaseUri: '' },
        settings: { clientId: '', clientSecret: '', authBaseUri: '' },
        defaults: { clientId: '872364219810-abc123xyz456.apps.googleusercontent.com', clientSecret: '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e', authBaseUri: 'https://accounts.application.com/o/oauth2/auth' },
        dialog(name) { return Alpine.$data(document.querySelector(`[data-dlg=${name}]`)); },
        iconFor(app) {
            const key = { 'google meet': 'google-meet' }[app.toLowerCase()] ?? app.toLowerCase();
            return this.icons[key] ? key : 'mailchimp';
        },
        toggle(id, connect) { this.integrations = this.integrations.map((item) => (item.id === id ? { ...item, connect } : item)); },
        openDetails(item) { this.current = item; this.dialog('details').show(); },
        openSettings(item) {
            this.current = item;
            this.settings = { clientId: item.clientId || this.defaults.clientId, clientSecret: item.clientSecret || this.defaults.clientSecret, authBaseUri: item.authBaseUri || this.defaults.authBaseUri };
            this.dialog('settings').show();
        },
        openDelete(item) { this.current = item; this.dialog('remove').show(); },
        saveSettings() {
            this.integrations = this.integrations.map((item) => (item.id === this.current.id ? { ...item, ...this.settings } : item));
            this.dialog('settings').close();
        },
        confirmDelete() {
            this.integrations = this.integrations.filter((item) => item.id !== this.current.id);
            this.dialog('remove').close();
        },
        addIntegration() {
            const data = {
                app: this.add.app,
                clientId: this.add.clientId || 'client-id-' + Date.now(),
                clientSecret: this.add.clientSecret || 'secret-' + Date.now(),
                authBaseUri: this.add.authBaseUri || 'https://accounts.application.com/o/oauth2/auth',
            };
            this.integrations = [{
                id: `custom-${Date.now()}`, title: data.app, description: `Connected ${data.app} integration for your team workspace.`, icon: this.iconFor(data.app),
                connect: true, appName: `${data.app} Workspace`, clientId: data.clientId, clientSecret: data.clientSecret, authBaseUri: data.authBaseUri,
            }, ...this.integrations];
            this.add.clientId = this.add.clientSecret = this.add.authBaseUri = '';
            this.dialog('create').close();
        },
    }"
